// ============================================================================
// POO UNIFICADA EN NODO CODE: Herencia de 3 niveles y Composición de Pago
// ============================================================================

class EntidadComercial {
  constructor(nombre, cedula, email = '') {
    this.nombre = nombre || '';
    this.cedula = cedula || '';
    this.email = email || '';
  }

  obtenerIdentificacion() {
    if (!this.cedula || !this.cedula.trim()) {
      return `${this.nombre || 'Entidad sin nombre'} [SIN CÉDULA REGISTRADA]`;
    }
    const correoInfo = this.email ? ` <${this.email}>` : '';
    return `${this.nombre} (ID: ${this.cedula.trim()})${correoInfo}`;
  }

  esIdentificacionValida() {
    return Boolean(this.cedula && this.cedula.toString().trim().length > 0);
  }
}

class Proveedor extends EntidadComercial {
  constructor(nombre, cedula, estadoHacienda = null, nivelRiesgo = null, email = '') {
    super(nombre, cedula, email);
    this.estadoHacienda = estadoHacienda;
    this.nivelRiesgo = nivelRiesgo;
  }

  evaluarRiesgo() {
    if (this.estadoHacienda === 'Desconocido') {
      this.nivelRiesgo = 'Alto';
      return {
        esRiesgoso: true,
        nivelRiesgo: this.nivelRiesgo,
        motivo: 'Error de conexión con Hacienda - Revisión manual'
      };
    }

    if (!this.estadoHacienda || this.estadoHacienda.trim() === '') {
      this.nivelRiesgo = 'Alto';
      return {
        esRiesgoso: true,
        nivelRiesgo: this.nivelRiesgo,
        motivo: 'Validación tributaria obligatoria pendiente ante Hacienda'
      };
    }

    const estadoNormalizado = this.estadoHacienda.trim().toLowerCase();
    if (estadoNormalizado === 'moroso') {
      this.nivelRiesgo = 'Alto';
      return {
        esRiesgoso: true,
        nivelRiesgo: this.nivelRiesgo,
        motivo: 'Proveedor figura como Moroso ante el Ministerio de Hacienda'
      };
    }

    if (estadoNormalizado === 'al dia' || estadoNormalizado === 'al día') {
      this.nivelRiesgo = 'Bajo';
      return {
        esRiesgoso: false,
        nivelRiesgo: this.nivelRiesgo,
        motivo: 'Proveedor al día con obligaciones tributarias'
      };
    }

    this.nivelRiesgo = 'Alto';
    return {
      esRiesgoso: true,
      nivelRiesgo: this.nivelRiesgo,
      motivo: `Estado tributario no concluyente (${this.estadoHacienda}) - Requiere revisión manual`
    };
  }
}

class ProveedorServicios extends Proveedor {
  constructor(
    nombre,
    cedula,
    estadoHacienda = null,
    nivelRiesgo = null,
    tipoServicio = 'Servicios Profesionales',
    porcentajeRetencion = 13,
    email = ''
  ) {
    super(nombre, cedula, estadoHacienda, nivelRiesgo, email);
    this.tipoServicio = tipoServicio || 'Servicios Profesionales';
    this.porcentajeRetencion = typeof porcentajeRetencion === 'number' ? porcentajeRetencion : 13;
  }

  calcularMontoNeto(montoBruto) {
    const bruto = Number(montoBruto) || 0;
    const factor = this.porcentajeRetencion > 1 ? this.porcentajeRetencion / 100 : this.porcentajeRetencion;
    const montoRetencion = Number((bruto * factor).toFixed(2));
    const montoNeto = Number((bruto - montoRetencion).toFixed(2));

    return {
      montoBruto: bruto,
      porcentajeRetencion: this.porcentajeRetencion,
      montoRetencion,
      montoNeto
    };
  }

  generarClavePago(idPago = '000', fecha = new Date().toISOString().split('T')[0]) {
    const anio = fecha ? (new Date(fecha).getFullYear() || 2026) : 2026;
    const randomHex = Math.random().toString(36).substring(2, 6).toUpperCase();
    return `REF-${anio}-PAY-${idPago}-${randomHex}`;
  }

  generarPayloadQR(montoNeto, clavePago, fecha = new Date().toISOString().split('T')[0]) {
    const ref = clavePago || this.generarClavePago('000', fecha);
    return `CLAVE: ${ref} | PROVEEDOR: ${this.nombre} | CEDULA: ${this.cedula} | MONTO_NETO: CRC ${Number(montoNeto).toFixed(2)} | FECHA: ${fecha} | SERVICIO: ${this.tipoServicio}`;
  }

  generarComprobante(idPago, montoNeto, fecha = new Date().toISOString().split('T')[0]) {
    const clavePago = this.generarClavePago(idPago, fecha);
    const datosParaQR = this.generarPayloadQR(montoNeto, clavePago, fecha);
    return { clavePago, datosParaQR };
  }
}

class Pago {
  constructor(idPago, monto, proveedor, fecha = new Date().toISOString().split('T')[0], estado = 'Pendiente') {
    this.idPago = idPago;
    this.monto = Number(monto);
    this.proveedor = proveedor;
    this.fecha = fecha;
    this.estado = estado;
    this.montoNeto = null;
    this.retencion = null;
    this.clavePago = null;
    this.datosParaQR = null;
    this.qrUrl = null;
    this.motivoRetencion = null;
  }

  procesarPago() {
    if (!this.proveedor || !this.proveedor.cedula || this.proveedor.cedula.toString().trim() === '') {
      this.estado = 'Error de validacion';
      this.motivoRetencion = 'Datos incompletos de origen: Cédula del proveedor faltante o nula.';
      this.clavePago = null;
      this.datosParaQR = null;
      this.qrUrl = null;
      return this;
    }

    if (isNaN(this.monto) || this.monto <= 0) {
      this.estado = 'Error de validacion';
      this.motivoRetencion = `Datos incompletos de origen: El monto (${this.monto}) debe ser estrictamente mayor a 0.`;
      this.clavePago = null;
      this.datosParaQR = null;
      this.qrUrl = null;
      return this;
    }

    if (this.proveedor.estadoHacienda === 'Desconocido') {
      this.estado = 'Retenido';
      this.motivoRetencion = 'Error de conexión con Hacienda - Revisión manual';
      this.clavePago = null;
      this.datosParaQR = null;
      this.qrUrl = null;
      return this;
    }

    if (!this.proveedor.estadoHacienda || this.proveedor.estadoHacienda.trim() === '') {
      this.estado = 'Retenido';
      this.motivoRetencion = 'Validación tributaria obligatoria: El proveedor no cuenta con verificación de Hacienda.';
      this.clavePago = null;
      this.datosParaQR = null;
      this.qrUrl = null;
      return this;
    }

    const evaluacionRiesgo = this.proveedor.evaluarRiesgo();

    if (evaluacionRiesgo.esRiesgoso) {
      this.estado = 'Retenido';
      this.motivoRetencion = evaluacionRiesgo.motivo;
      this.clavePago = null;
      this.datosParaQR = null;
      this.qrUrl = null;
      return this;
    }

    this.estado = 'Aprobado';
    this.motivoRetencion = null;

    const desglose = this.proveedor.calcularMontoNeto(this.monto);
    this.montoNeto = desglose.montoNeto;
    this.retencion = desglose.montoRetencion;

    const comprobante = this.proveedor.generarComprobante(this.idPago, this.montoNeto, this.fecha);
    this.clavePago = comprobante.clavePago;
    this.datosParaQR = comprobante.datosParaQR;
    this.qrUrl = `https://api.qrserver.com/v1/create-qr-code/?size=250x250&data=${encodeURIComponent(this.datosParaQR)}`;

    return this;
  }

  toObjeto() {
    return {
      id: this.idPago,
      idPago: this.idPago,
      fecha: this.fecha,
      monto: this.monto,
      estado: this.estado,
      montoNeto: this.montoNeto,
      retencion: this.retencion,
      clavePago: this.clavePago,
      motivoRetencion: this.motivoRetencion,
      datosParaQR: this.datosParaQR,
      qrUrl: this.qrUrl,
      proveedor: {
        nombre: this.proveedor.nombre,
        cedula: this.proveedor.cedula,
        email: this.proveedor.email,
        tipoServicio: this.proveedor.tipoServicio,
        porcentajeRetencion: this.proveedor.porcentajeRetencion,
        estadoHacienda: this.proveedor.estadoHacienda,
        nivelRiesgo: this.proveedor.nivelRiesgo
      }
    };
  }
}

let pagosOriginales = [];
try {
  pagosOriginales = $('HTTP - Obtener Pagos Pendientes (JSON Server)').all();
} catch (e) {
  pagosOriginales = [];
}

const haciendaItems = $input.all();
const resultados = [];

for (let i = 0; i < pagosOriginales.length; i++) {
  const row = pagosOriginales[i].json;
  const provData = row.proveedor || {};
  const hItem = haciendaItems[i] ? haciendaItems[i].json : null;

  let estadoHacienda = 'Desconocido';

  if (hItem) {
    const rawBody = hItem.body !== undefined ? hItem.body : hItem;
    const data = Array.isArray(rawBody) ? rawBody[0] : rawBody;

    if (data && (data.estadoTributario || data.moroso)) {
      if (data.moroso === 'SI' || data.estadoTributario === 'Moroso') {
        estadoHacienda = 'Moroso';
      } else if (data.moroso === 'NO' || data.estadoTributario === 'Al dia') {
        estadoHacienda = 'Al dia';
      }
    } else if (provData.cedula && provData.cedula.trim() !== '') {
      estadoHacienda = 'Desconocido';
    }
  }

  const proveedor = new ProveedorServicios(
    provData.nombre,
    provData.cedula,
    estadoHacienda,
    null,
    provData.tipoServicio,
    provData.porcentajeRetencion,
    provData.email || ''
  );

  const pago = new Pago(
    row.idPago || row.id,
    row.monto,
    proveedor,
    row.fecha || new Date().toISOString().split('T')[0]
  );

  pago.procesarPago();
  resultados.push({ json: pago.toObjeto() });
}

return resultados;
